using System.IdentityModel.Tokens.Jwt;
using System.Text.Json;
using LifeVerse.Api.Data;
using Microsoft.EntityFrameworkCore;

namespace LifeVerse.Api.Modules.Scripting;

public sealed record ObjectScriptRequest(string Name, string Source, string EventName = "on_start");
public sealed record ScriptStateRequest(string ValueJson);
public sealed record ScriptMessageRequest(Guid ToObjectId, string Channel, string PayloadJson);
public sealed record HudDefinitionRequest(string Name, string LayoutJson, Guid? ScriptId);
public sealed record HudEquipRequest(int Priority = 0);

public static partial class ScriptingEndpoints
{
    public static IEndpointRouteBuilder MapScriptingEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var group = endpoints.MapGroup("/api/v1/worlds/{islandId:guid}/objects/{objectId:guid}/scripts").WithTags("Scripting").RequireAuthorization(); group.MapGet("", ListAsync); group.MapGet("/{scriptId:guid}", GetOneAsync); group.MapPost("/validate", ValidateAsync); group.MapPost("/reset", ResetAllAsync); group.MapPost("/{scriptId:guid}/reset", ResetOneAsync); group.MapDelete("/{scriptId:guid}", DeleteOneAsync); group.MapGet("/{scriptId:guid}/executions", ExecutionsAsync); group.MapPost("", CreateAsync); group.MapPut("/{scriptId:guid}", UpdateAsync); group.MapPost("/{scriptId:guid}/run", () => RunMoved()); group.MapPost("/run", () => RunMoved()); group.MapPost("/{scriptId:guid}/stop", StopAsync); group.MapGet("/{scriptId:guid}/state", StateAsync); group.MapGet("/{scriptId:guid}/runtime", RuntimeAsync); group.MapPut("/{scriptId:guid}/permissions/{permission}", SetOwnerPermissionAsync); group.MapPost("/{scriptId:guid}/pause", (Guid islandId, Guid objectId, Guid scriptId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) => PauseAsync(islandId, objectId, scriptId, true, context, db, clock, ct)); group.MapPost("/{scriptId:guid}/resume", (Guid islandId, Guid objectId, Guid scriptId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) => PauseAsync(islandId, objectId, scriptId, false, context, db, clock, ct)); group.MapPut("/{scriptId:guid}/state/{key}", SetStateAsync); group.MapPost("/{scriptId:guid}/messages", SendMessageAsync); group.MapGet("/{scriptId:guid}/messages/{channel}", DrainMessagesAsync);
        endpoints.MapGet("/api/v1/worlds/{islandId:guid}/script-usage", UsageAsync).WithTags("Scripting").RequireAuthorization();
        endpoints.MapGet("/api/v1/scripting/reference", () => Reference()).WithTags("Scripting");
        endpoints.MapGet("/api/v1/scripting/templates", () => Results.Ok(Templates.Concat(SoundTemplates))).WithTags("Scripting");
        var huds = endpoints.MapGroup("/api/v1/huds").WithTags("HUDs").RequireAuthorization(); huds.MapGet("", ListHudsAsync); huds.MapPost("", CreateHudAsync); huds.MapPut("/{hudId:guid}", UpdateHudAsync); huds.MapDelete("/{hudId:guid}", DeleteHudAsync); huds.MapPost("/{hudId:guid}/equip", EquipHudAsync); huds.MapDelete("/{hudId:guid}/equip", UnequipHudAsync);
        return endpoints;
    }
    /// Scripts run on the island server (real sandbox, real world events); the API no longer executes user code.
    private static IResult RunMoved() => Results.Problem(statusCode: 410, title: "Scripts run on the island server. Save the script and touch the object in the world.");

    private static readonly object[] Templates = [new { name = "porta_automatica", eventName = "on_touch", source = "function on_touch(event)\n  object.set_position({x=1,y=0,z=0})\nend" }, new { name = "elevador", eventName = "on_timer", source = "function on_timer(event)\n  object.set_position({x=0,y=event.height,z=0})\nend" }, new { name = "lampada", eventName = "on_message", source = "function on_message(event)\n  object.set_material({emission=event.color})\nend" }, new { name = "plataforma", eventName = "on_timer", source = "function on_timer(event)\n  object.set_position(event.position)\nend" }, new { name = "botao_mensagem", eventName = "on_touch", source = "function on_touch(event)\n  object.send_message(event.message)\nend" }, new { name = "som", eventName = "on_touch", source = "function on_touch(event)\n  object.play_sound(event.sound)\nend" }, new { name = "teleportador", eventName = "on_touch", source = "function on_touch(event)\n  object.teleport_authorized(event.user_id,event.destination)\nend" }, new { name = "placar", eventName = "on_message", source = "function on_message(event)\n  object.state_set('score',event.score)\nend" }, new { name = "temporizador", eventName = "on_start", source = "function on_start(event)\n  object.create_timer(1.0)\nend" }, new { name = "painel", eventName = "on_enter", source = "function on_enter(event)\n  object.send_message('Bem-vindo')\nend" }];
    private static async Task<IResult> ListAsync(Guid islandId, Guid objectId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); var obj = await db.BuildObjects.AsNoTracking().SingleOrDefaultAsync(x => x.Id == objectId && x.IslandId == islandId && x.DeletedAt == null, ct); if (obj is null) return Results.NotFound(); if (!await CanEditAsync(db, islandId, user, ct)) return Results.Forbid(); return Results.Ok(await db.ObjectScripts.AsNoTracking().Where(x => x.ObjectId == objectId).Select(x => new { x.Id, x.Name, x.Version, x.Status, x.InstructionBudget, x.MemoryLimitKb, x.UpdatedAt }).ToListAsync(ct)); }
    internal static async Task<IResult> CreateAsync(Guid islandId, Guid objectId, ObjectScriptRequest request, HttpContext context, LifeVerseDbContext db, LuaRuntimeOptions options, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); if (!await CanEditAsync(db, islandId, user, ct)) return Results.Forbid(); var target = await db.BuildObjects.AsNoTracking().Select(x => new { x.Id, x.IslandId, x.DeletedAt, x.OwnerRights }).SingleOrDefaultAsync(x => x.Id == objectId && x.IslandId == islandId && x.DeletedAt == null, ct); if (target is null) return Results.NotFound(); if (!LifeVerse.Shared.Items.ItemRights.Has(target.OwnerRights, LifeVerse.Shared.Items.Right.Modify)) return Results.Json(new { error = "no_modify" }, statusCode: StatusCodes.Status403Forbidden); /* a script is part of what an object is made of: it can only be added to an object that may be modified */ if (!LuaSafetyValidator.IsEvent(request.EventName) && !LifeVerse.Scripting.ScriptCatalog.EventNames.Contains(request.EventName)) return Results.BadRequest(new { error = "Unsupported event" }); var compiled = LifeVerse.Scripting.ScriptCompiler.Compile(request.Source); if (!compiled.Valid) return Results.ValidationProblem(new Dictionary<string, string[]> { ["source"] = [Describe(compiled)] }); var name = request.Name.Trim(); if (name.Length is < 1 or > 120) return Results.BadRequest(new { error = "Script name is required." }); var now = clock.GetUtcNow(); var script = new ObjectScript { Id = Guid.NewGuid(), ObjectId = objectId, OwnerUserId = user, Name = name, Source = request.Source, Version = 1, Status = "active", InstructionBudget = options.MaxInstructions, MemoryLimitKb = options.MaxMemoryKb, CreatedAt = now, UpdatedAt = now }; db.ObjectScripts.Add(script); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/worlds/{islandId}/objects/{objectId}/scripts/{script.Id}", new { script.Id, script.Name, script.Version, warnings = compiled.Diagnostics.Where(d => d.Severity == "warning").Select(d => new { d.Line, d.Message }) }); }
    internal static async Task<IResult> UpdateAsync(Guid islandId, Guid objectId, Guid scriptId, ObjectScriptRequest request, HttpContext context, LifeVerseDbContext db, LuaRuntimeOptions options, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); if (!await CanEditAsync(db, islandId, user, ct)) return Results.Forbid(); var script = await db.ObjectScripts.SingleOrDefaultAsync(x => x.Id == scriptId && x.ObjectId == objectId, ct); if (script is null) return Results.NotFound(); if (!await db.BuildObjects.AsNoTracking().AnyAsync(x => x.Id == objectId && x.DeletedAt == null && (x.OwnerRights & 2) != 0, ct)) return Results.Json(new { error = "no_modify" }, statusCode: StatusCodes.Status403Forbidden); /* the source of a script can only be changed when the object may be modified */ var compiled = LifeVerse.Scripting.ScriptCompiler.Compile(request.Source); if (!compiled.Valid) return Results.ValidationProblem(new Dictionary<string, string[]> { ["source"] = [Describe(compiled)] }); script.Source = request.Source; script.Name = request.Name.Trim()[..Math.Min(request.Name.Trim().Length, 120)]; script.Version++; script.Status = "active"; script.UpdatedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.Ok(new { script.Id, script.Version, warnings = compiled.Diagnostics.Where(d => d.Severity == "warning").Select(d => new { d.Line, d.Message }) }); }
    private static async Task<IResult> RunAsync(Guid islandId, Guid objectId, Guid scriptId, RunScriptRequest request, HttpContext context, LifeVerseDbContext db, LuaSandboxService sandbox, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); if (!await CanEditAsync(db, islandId, user, ct)) return Results.Forbid(); var script = await db.ObjectScripts.SingleOrDefaultAsync(x => x.Id == scriptId && x.ObjectId == objectId && x.Status == "active", ct); if (script is null) return Results.NotFound(); if (!sandbox.TryAcquireEvent(script.Id)) return Results.StatusCode(StatusCodes.Status429TooManyRequests); var result = await sandbox.ExecuteAsync(script.Source, request.EventName, request.PayloadJson ?? "{}", ct); db.ScriptExecutions.Add(new ScriptExecution { Id = Guid.NewGuid(), ScriptId = script.Id, EventName = request.EventName, Status = result.Status, InstructionCount = result.Instructions, Error = result.Error ?? string.Empty, CreatedAt = clock.GetUtcNow() }); if (result.Status is "rejected" or "timeout" or "failed") script.Status = result.Status == "timeout" ? "quarantined" : script.Status; await db.SaveChangesAsync(ct); return result.Status == "worker_unavailable" ? Results.Problem(statusCode: 503, title: "Lua worker unavailable.") : Results.Ok(result); }
    private static async Task<IResult> RunLatestAsync(Guid islandId, Guid objectId, RunScriptRequest request, HttpContext context, LifeVerseDbContext db, LuaSandboxService sandbox, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); if (!await CanEditAsync(db, islandId, user, ct)) return Results.Forbid(); var script = await db.ObjectScripts.Where(x => x.ObjectId == objectId && x.Status == "active").OrderByDescending(x => x.Version).FirstOrDefaultAsync(ct); if (script is null) return Results.NotFound(); return !sandbox.TryAcquireEvent(script.Id) ? Results.StatusCode(StatusCodes.Status429TooManyRequests) : await RunStoredAsync(script, request, db, sandbox, clock, ct); }
    private static async Task<IResult> RunStoredAsync(ObjectScript script, RunScriptRequest request, LifeVerseDbContext db, LuaSandboxService sandbox, TimeProvider clock, CancellationToken ct) { var result = await sandbox.ExecuteAsync(script.Source, request.EventName, request.PayloadJson ?? "{}", ct); db.ScriptExecutions.Add(new ScriptExecution { Id = Guid.NewGuid(), ScriptId = script.Id, EventName = request.EventName, Status = result.Status, InstructionCount = result.Instructions, Error = result.Error ?? string.Empty, CreatedAt = clock.GetUtcNow() }); if (result.Status is "rejected" or "timeout" or "failed") script.Status = result.Status == "timeout" ? "quarantined" : script.Status; await db.SaveChangesAsync(ct); return result.Status == "worker_unavailable" ? Results.Problem(statusCode: 503, title: "Lua worker unavailable.") : Results.Ok(result); }
    private static async Task<IResult> StopAsync(Guid islandId, Guid objectId, Guid scriptId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); if (!await CanEditAsync(db, islandId, user, ct)) return Results.Forbid(); var script = await db.ObjectScripts.SingleOrDefaultAsync(x => x.Id == scriptId && x.ObjectId == objectId, ct); if (script is null) return Results.NotFound(); script.Status = "stopped"; await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> StateAsync(Guid islandId, Guid objectId, Guid scriptId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); if (!await CanEditAsync(db, islandId, user, ct)) return Results.Forbid(); return Results.Ok(await db.ScriptStates.AsNoTracking().Where(x => x.ScriptId == scriptId).Select(x => new { x.Key, x.ValueJson, x.UpdatedAt }).ToListAsync(ct)); }
    private static async Task<IResult> SetStateAsync(Guid islandId, Guid objectId, Guid scriptId, string key, ScriptStateRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); if (!await CanEditAsync(db, islandId, user, ct)) return Results.Forbid(); if (key.Length is < 1 or > 64 || request.ValueJson.Length > 8192) return Results.BadRequest(); try { using var json = JsonDocument.Parse(request.ValueJson); if (!IsSimpleValue(json.RootElement, 0)) return Results.BadRequest(new { error = "Only primitive values and limited arrays/objects are allowed." }); } catch (JsonException) { return Results.BadRequest(new { error = "ValueJson must be valid JSON." }); } var state = await db.ScriptStates.SingleOrDefaultAsync(x => x.ScriptId == scriptId && x.Key == key, ct); if (state is null) db.ScriptStates.Add(new ScriptState { Id = Guid.NewGuid(), ScriptId = scriptId, Key = key, ValueJson = request.ValueJson, UpdatedAt = clock.GetUtcNow() }); else { state.ValueJson = request.ValueJson; state.UpdatedAt = clock.GetUtcNow(); } await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> SendMessageAsync(Guid islandId, Guid objectId, Guid scriptId, ScriptMessageRequest request, HttpContext context, LifeVerseDbContext db, ScriptMessagingService messaging, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); if (!await CanEditAsync(db, islandId, user, ct)) return Results.Forbid(); if (request.Channel.Length is < 1 or > 48 || request.PayloadJson.Length > 4096 || !await db.BuildObjects.AnyAsync(x => x.Id == request.ToObjectId && x.IslandId == islandId && x.DeletedAt == null, ct)) return Results.BadRequest(); try { using var payload = JsonDocument.Parse(request.PayloadJson); if (!IsSimpleValue(payload.RootElement, 0)) return Results.BadRequest(new { error = "Message payload is too complex." }); } catch (JsonException) { return Results.BadRequest(); } var message = new ScriptMessage(objectId, request.ToObjectId, request.Channel, request.PayloadJson, clock.GetUtcNow()); return messaging.TryEnqueue(message) ? Results.Accepted(value: new { queued = true, expiresInSeconds = 120 }) : Results.StatusCode(StatusCodes.Status429TooManyRequests); }
    private static async Task<IResult> DrainMessagesAsync(Guid islandId, Guid objectId, Guid scriptId, string channel, HttpContext context, LifeVerseDbContext db, ScriptMessagingService messaging, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); if (!await CanEditAsync(db, islandId, user, ct)) return Results.Forbid(); if (channel.Length is < 1 or > 48) return Results.BadRequest(); return Results.Ok(new { messages = messaging.Drain(objectId, channel), protocolVersion = 1 }); }
    private static async Task<IResult> ListHudsAsync(HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); return Results.Ok(await db.HudDefinitions.AsNoTracking().Where(x => x.OwnerUserId == user && x.DeletedAt == null).Select(x => new { x.Id, x.Name, x.LayoutJson, x.ScriptId, x.Version }).ToListAsync(ct)); }
    private static async Task<IResult> CreateHudAsync(HudDefinitionRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); if (!ValidLayout(request.LayoutJson)) return Results.BadRequest(new { error = "Invalid HUD layout." }); var name = request.Name.Trim(); if (name.Length is < 1 or > 120) return Results.BadRequest(new { error = "HUD name is required." }); var now = clock.GetUtcNow(); var hud = new HudDefinition { Id = Guid.NewGuid(), OwnerUserId = user, Name = name, LayoutJson = request.LayoutJson, ScriptId = request.ScriptId, CreatedAt = now, UpdatedAt = now }; var asset = new Asset { Id = Guid.NewGuid(), OwnerUserId = user, CreatorUserId = user, Name = name, Category = "huds", Description = "LifeVerse HUD definition", LicenseJson = "{\"copy\":true,\"modify\":true,\"transfer\":false}", CreatedAt = now, UpdatedAt = now }; db.HudDefinitions.Add(hud); db.Assets.Add(asset); db.InventoryItems.Add(new InventoryItem { Id = Guid.NewGuid(), OwnerUserId = user, AssetId = asset.Id, DisplayName = name, CreatedAt = now, UpdatedAt = now }); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/huds/{hud.Id}", hud); }
    private static async Task<IResult> UpdateHudAsync(Guid hudId, HudDefinitionRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); var hud = await db.HudDefinitions.SingleOrDefaultAsync(x => x.Id == hudId && x.OwnerUserId == user && x.DeletedAt == null, ct); if (hud is null) return Results.NotFound(); if (!ValidLayout(request.LayoutJson)) return Results.BadRequest(); hud.Name = request.Name.Trim()[..Math.Min(request.Name.Trim().Length, 120)]; hud.LayoutJson = request.LayoutJson; hud.ScriptId = request.ScriptId; hud.Version++; hud.UpdatedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.Ok(hud); }
    private static async Task<IResult> DeleteHudAsync(Guid hudId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); var hud = await db.HudDefinitions.SingleOrDefaultAsync(x => x.Id == hudId && x.OwnerUserId == user && x.DeletedAt == null, ct); if (hud is null) return Results.NotFound(); hud.DeletedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> EquipHudAsync(Guid hudId, HudEquipRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); if (request.Priority is < 0 or > 15) return Results.BadRequest(new { error = "Priority must be between 0 and 15." }); if (!await db.HudDefinitions.AnyAsync(x => x.Id == hudId && x.OwnerUserId == user && x.DeletedAt == null, ct)) return Results.NotFound(); var avatar = await db.Avatars.Include(x => x.EquippedItems).SingleOrDefaultAsync(x => x.UserId == user, ct); if (avatar is null) return Results.NotFound(); var slot = $"hud:{request.Priority}"; var existing = avatar.EquippedItems.SingleOrDefault(x => x.Slot == slot); if (existing is null) db.EquippedItems.Add(new EquippedItem { Id = Guid.NewGuid(), AvatarId = avatar.Id, Slot = slot, ItemKey = $"hud:{hudId}", TintColor = "#FFFFFF", EquippedAt = clock.GetUtcNow() }); else { existing.ItemKey = $"hud:{hudId}"; existing.EquippedAt = clock.GetUtcNow(); } await db.SaveChangesAsync(ct); return Results.Ok(new { hudId, priority = request.Priority, equipped = true }); }
    private static async Task<IResult> UnequipHudAsync(Guid hudId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!TryUser(context, out var user)) return Results.Unauthorized(); var avatar = await db.Avatars.Include(x => x.EquippedItems).SingleOrDefaultAsync(x => x.UserId == user, ct); if (avatar is null) return Results.NotFound(); var keys = avatar.EquippedItems.Where(x => x.ItemKey == $"hud:{hudId}").ToList(); if (keys.Count > 0) db.EquippedItems.RemoveRange(keys); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static bool ValidLayout(string layout) { if (layout.Length > 256_000) return false; try { using var doc = JsonDocument.Parse(layout); return doc.RootElement.ValueKind == JsonValueKind.Object; } catch { return false; } }
    private static bool IsSimpleValue(JsonElement value, int depth) { if (depth > 4) return false; return value.ValueKind switch { JsonValueKind.String => value.GetString()?.Length <= 1024, JsonValueKind.Number or JsonValueKind.True or JsonValueKind.False or JsonValueKind.Null => true, JsonValueKind.Array => value.GetArrayLength() <= 64 && value.EnumerateArray().All(x => IsSimpleValue(x, depth + 1)), JsonValueKind.Object => value.EnumerateObject().Count() <= 64 && value.EnumerateObject().All(x => x.Name.Length <= 64 && IsSimpleValue(x.Value, depth + 1)), _ => false }; }
    private static async Task<bool> CanEditAsync(LifeVerseDbContext db, Guid islandId, Guid user, CancellationToken ct) => await db.Islands.AnyAsync(x => x.Id == islandId && x.DeletedAt == null && x.OwnerUserId == user, ct) || await db.IslandPermissions.AnyAsync(x => x.IslandId == islandId && x.UserId == user && x.RevokedAt == null && (x.Permission == "edit" || x.Permission == "run_scripts" || x.Permission == "admin"), ct);
    private static bool TryUser(HttpContext context, out Guid user) => Guid.TryParse(context.User.FindFirst(JwtRegisteredClaimNames.Sub)?.Value, out user);
}

public sealed record RunScriptRequest(string EventName, string? PayloadJson);
